<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/bootstrap.php'; require_method('GET'); $u=current_user(); $id=trim((string)($_GET['id']??''));
$sql="SELECT c.id internalId,c.public_id id,c.name,c.subject,c.body,c.body_format bodyFormat,c.status,c.total_recipients recipients,c.sent_count sent,c.failed_count failed,c.pending_count pending,c.created_at createdAt,c.scheduled_at schedule,c.started_at startedAt,c.completed_at completedAt,a.public_id senderAccountId,a.sender_email sender FROM campaigns c JOIN smtp_accounts a ON a.id=c.smtp_account_id AND a.tenant_id=c.tenant_id WHERE c.tenant_id=? AND c.public_id=?"; $p=[$u['tenant_id'],$id]; if($u['role']==='MEMBER'){$sql.=' AND c.created_by=?';$p[]=$u['id'];}
$s=db()->prepare($sql);$s->execute($p);$c=$s->fetch();if(!$c)throw new ApiError(404,'Campaign not found.'); [$page,$per,$offset]=pagination();$recipientWhere='tenant_id=? AND campaign_id=?';$recipientParams=[$u['tenant_id'],$c['internalId']];$status=strtoupper(trim((string)($_GET['status']??'')));if(in_array($status,['PENDING','PROCESSING','SENT','FAILED','RETRY','CANCELLED'],true)){$recipientWhere.=' AND status=?';$recipientParams[]=$status;}$count=db()->prepare("SELECT COUNT(*) FROM campaign_recipients WHERE {$recipientWhere}");$count->execute($recipientParams);$recipientTotal=(int)$count->fetchColumn();
$r=db()->prepare("SELECT id,recipient_name name,recipient_email email,status,attempts,sent_at sentAt,last_error failureReason,COALESCE(failure_category,'') failureCategory FROM campaign_recipients WHERE {$recipientWhere} ORDER BY id LIMIT ? OFFSET ?");$i=1;foreach($recipientParams as $value)$r->bindValue($i++,$value);$r->bindValue($i++,$per,PDO::PARAM_INT);$r->bindValue($i,$offset,PDO::PARAM_INT);$r->execute();unset($c['internalId']);respond(['campaign'=>$c,'recipients'=>$r->fetchAll()],200,['page'=>$page,'perPage'=>$per,'total'=>$recipientTotal,'pages'=>(int)ceil($recipientTotal/$per)]);
